use super::misc::in_circumsphere;
use super::misc::orient3d;
use super::misc::rc3;
use super::tet_entry::TetEntry;
use crate::mesh::types::Point;
use std::collections::{HashMap, HashSet};

/// Incremental Delaunay tetrahedralisation.
///
/// Tets are stored in a `Vec<Option<TetEntry>>` with a free-list of vacated
/// slots; deletion preserves the indices of surviving tets so neighbour
/// pointers stay valid. Insertion uses a visibility walk (seeded from the
/// last successful insertion) to find a containing tet, then a BFS over the
/// neighbour graph to discover the Bowyer-Watson cavity.
pub(super) struct Delaunay3D {
    pub(super) points: Vec<Point>,
    pub(super) tets: Vec<Option<TetEntry>>,
    pub(super) free_slots: Vec<usize>,
    pub(super) hull_faces: Vec<[usize; 3]>,
    /// Number of real (user-supplied) points. Super-tet vertices, when
    /// present, occupy indices `num_real..num_real + 4`.
    pub(super) num_real: usize,
    /// Last successfully inserted tet — used to seed the walk for the next
    /// insertion. Inputs that are spatially coherent get very short walks.
    pub(super) last_inserted: Option<usize>,
}

impl Delaunay3D {
    pub(super) fn new() -> Self {
        Self {
            points: Vec::new(),
            tets: Vec::new(),
            free_slots: Vec::new(),
            hull_faces: Vec::new(),
            num_real: 0,
            last_inserted: None,
        }
    }

    pub(super) fn is_super(&self, idx: usize) -> bool {
        idx >= self.num_real
    }

    pub(super) fn add_point(&mut self, p: Point) -> usize {
        let idx = self.points.len();
        self.points.push(p);
        idx
    }

    pub(super) fn alloc_tet(&mut self, entry: TetEntry) -> usize {
        if let Some(slot) = self.free_slots.pop() {
            self.tets[slot] = Some(entry);
            slot
        } else {
            self.tets.push(Some(entry));
            self.tets.len() - 1
        }
    }

    pub(super) fn free_tet(&mut self, idx: usize) {
        self.tets[idx] = None;
        self.free_slots.push(idx);
    }

    pub(super) fn get(&self, idx: usize) -> &TetEntry {
        self.tets[idx].as_ref().expect("tet slot vacant")
    }

    pub(super) fn vertex_points(&self, t: &TetEntry) -> [Point; 4] {
        [
            self.points[t.vertices[0]],
            self.points[t.vertices[1]],
            self.points[t.vertices[2]],
            self.points[t.vertices[3]],
        ]
    }

    pub(super) fn first_live_tet(&self) -> Option<usize> {
        self.tets.iter().position(|t| t.is_some())
    }

    pub(super) fn compute_bounding_box(&self) -> (Point, Point) {
        let mut min = Point::new_3d(f64::INFINITY, f64::INFINITY, f64::INFINITY);
        let mut max = Point::new_3d(f64::NEG_INFINITY, f64::NEG_INFINITY, f64::NEG_INFINITY);
        for p in &self.points {
            min.x = min.x.min(p.x);
            min.y = min.y.min(p.y);
            min.z = min.z.min(p.z);
            max.x = max.x.max(p.x);
            max.y = max.y.max(p.y);
            max.z = max.z.max(p.z);
        }
        (min, max)
    }

    pub(super) fn initialize_super_tetrahedron(&mut self) {
        let (min, max) = self.compute_bounding_box();
        let dx = max.x - min.x;
        let dy = max.y - min.y;
        let dz = max.z - min.z;
        let diag = (dx * dx + dy * dy + dz * dz).sqrt();
        let cx = (min.x + max.x) / 2.0;
        let cy = (min.y + max.y) / 2.0;
        let cz = (min.z + max.z) / 2.0;
        let scale = diag * 10.0;

        let p0 = Point::new_3d(cx, cy, cz + scale);
        let p1 = Point::new_3d(cx - scale, cy - scale * 0.5, cz - scale * 0.5);
        let p2 = Point::new_3d(cx + scale, cy - scale * 0.5, cz - scale * 0.5);
        let p3 = Point::new_3d(cx, cy + scale, cz - scale * 0.5);
        let i0 = self.add_point(p0);
        let i1 = self.add_point(p1);
        let i2 = self.add_point(p2);
        let i3 = self.add_point(p3);

        // Enforce positive orientation per robust::orient3d so the
        // FACE_OUTWARD convention holds for the seed tet.
        let verts = [
            self.points[i0],
            self.points[i1],
            self.points[i2],
            self.points[i3],
        ];
        let entry = if orient3d(&verts) > 0.0 {
            TetEntry {
                vertices: [i0, i1, i2, i3],
                neighbors: [None; 4],
            }
        } else {
            TetEntry {
                vertices: [i0, i2, i1, i3],
                neighbors: [None; 4],
            }
        };
        let slot = self.alloc_tet(entry);
        self.last_inserted = Some(slot);
    }

    /// Visibility walk: starting from `seed`, step face-to-face toward
    /// `point`. Returns the index of a tet that contains `point` (in the
    /// orient3d-strict sense), or `None` if the walk reached a hull face —
    /// which should not happen during Bowyer-Watson because the super-tet
    /// covers every input.
    pub(super) fn locate(&self, point: Point, seed: usize) -> Option<usize> {
        let mut current = seed;
        let mut prev_face: Option<usize> = None;
        // Worst-case bound. Visibility walks on a Delaunay triangulation are
        // O(n^{1/3}) on average and bounded by the number of tets in the
        // worst case (degenerate alignments).
        let max_steps = self.tets.len().saturating_mul(4) + 32;
        for _ in 0..max_steps {
            let tet = self.get(current);
            let mut step_to: Option<usize> = None;
            for i in 0..4 {
                if Some(i) == prev_face {
                    continue;
                }
                let f = tet.face_verts(i);
                let a = self.points[f[0]];
                let b = self.points[f[1]];
                let c = self.points[f[2]];
                let s = robust::orient3d(rc3(a), rc3(b), rc3(c), rc3(point));
                if s < 0.0 {
                    // `point` lies on the opposite side from `v_i`, so it is
                    // outside the tet across face `i` — walk across.
                    step_to = Some(i);
                    break;
                }
            }
            match step_to {
                None => return Some(current),
                Some(face) => {
                    let next = tet.neighbors[face]?;
                    // Find which face of `next` looks back at `current` so we
                    // don't immediately cross back.
                    prev_face = self
                        .get(next)
                        .neighbors
                        .iter()
                        .position(|n| *n == Some(current));
                    current = next;
                }
            }
        }
        None
    }

    pub(super) fn find_hull_faces(&mut self) {
        self.hull_faces.clear();
        let mut face_count: HashMap<[usize; 3], i32> = HashMap::new();
        for tet in self.tets.iter().flatten() {
            if tet.vertices.iter().any(|&i| self.is_super(i)) {
                continue;
            }
            for i in 0..4 {
                let mut sorted = tet.face_verts(i);
                sorted.sort_unstable();
                *face_count.entry(sorted).or_insert(0) += 1;
            }
        }
        let mut hull_faces: Vec<[usize; 3]> = face_count
            .into_iter()
            .filter_map(|(face, count)| (count == 1).then_some(face))
            .collect();
        hull_faces.sort_unstable();
        self.hull_faces = hull_faces;
    }

    pub(super) fn tetrahedralize(&mut self) {
        if self.points.len() < 4 {
            return;
        }
        self.num_real = self.points.len();
        self.initialize_super_tetrahedron();
        for pi in 0..self.num_real {
            self.insert_point(pi);
        }
        self.find_hull_faces();
    }

    /// Bowyer-Watson insertion of `pi` into the current triangulation.
    ///
    /// 1. Walk from `last_inserted` to find any tet whose circumsphere
    ///    contains `pi`.
    /// 2. BFS over the neighbour graph to collect every tet whose
    ///    circumsphere contains `pi` (the cavity).
    /// 3. Free the cavity tets and rebuild the cavity with new tets formed
    ///    by connecting each cavity-boundary face to `pi`, rewiring the
    ///    neighbour pointers on both sides of each face.
    pub(super) fn insert_point(&mut self, pi: usize) {
        let pt = self.points[pi];
        let Some(seed) = self.last_inserted.or_else(|| self.first_live_tet()) else {
            return;
        };
        // 1. Locate.
        let Some(start) = self.locate(pt, seed) else {
            return;
        };

        // 2. BFS the cavity. A neighbour of a bad tet is also bad iff its
        // circumsphere contains `pi`. The BFS terminates when every frontier
        // tet's external faces lead out of the cavity.
        let mut bad: HashSet<usize> = HashSet::new();
        let mut queue = vec![start];
        bad.insert(start);
        while let Some(t) = queue.pop() {
            // Snapshot neighbours; we can't hold a borrow across the inner
            // circumsphere test which re-reads `self.points`.
            let nbrs = self.get(t).neighbors;
            for nbr in nbrs.into_iter().flatten() {
                if bad.contains(&nbr) {
                    continue;
                }
                let verts = self.vertex_points(self.get(nbr));
                if in_circumsphere(&pt, &verts) {
                    bad.insert(nbr);
                    queue.push(nbr);
                }
            }
        }

        // Make every subsequent cavity operation deterministic. The cavity
        // membership test intentionally uses a hash set for O(1) lookups,
        // but hash iteration order must never choose the emitted tetrahedron
        // order or the reusable slot order.
        let mut bad_tets: Vec<usize> = bad.iter().copied().collect();
        bad_tets.sort_unstable();

        // 3a. Identify cavity boundary faces (each bad-tet face whose other
        // side is *not* in `bad`) along with their external neighbour and
        // the face index of that neighbour facing the cavity.
        type CavityFace = ([usize; 3], Option<usize>, usize);
        let mut cavity: Vec<CavityFace> = Vec::new();
        for &bt in &bad_tets {
            let tet = *self.get(bt);
            for face_idx in 0..4 {
                let outside_nbr = tet.neighbors[face_idx];
                let external = match outside_nbr {
                    Some(n) => !bad.contains(&n),
                    None => true,
                };
                if !external {
                    continue;
                }
                let face = tet.face_verts(face_idx);
                let ext_face_idx = match outside_nbr {
                    Some(n) => {
                        let mut sorted = face;
                        sorted.sort_unstable();
                        self.get(n)
                            .face_index_for_vertex_set(&sorted)
                            .expect("external neighbour must share the boundary face")
                    }
                    None => 0,
                };
                cavity.push((face, outside_nbr, ext_face_idx));
            }
        }

        // 3b. Free cavity tets. Their slots become reusable; existing
        // neighbour pointers from outside the cavity still reference these
        // slots and will be rewired below.
        for &bt in &bad_tets {
            self.free_tet(bt);
        }

        // 3c. Build the new tets. For each cavity face (a,b,c) whose
        // bad-tet-interior side contained `pi`, the new tet `[a,b,c,pi]` is
        // already positively oriented per robust::orient3d because the
        // cavity faces are emitted in their FACE_OUTWARD ordering relative
        // to the *bad* tet's positive orientation — the same ordering puts
        // `pi` on the positive side. Face index 3 of the new tet (opposite
        // `pi`) is the cavity boundary; the other three faces contain `pi`
        // and are shared with adjacent new tets.
        //
        // Inter-new-tet matching: two new tets share the face containing
        // `pi` iff their cavity faces share an edge. Hash by sorted edge.
        let mut edge_pairing: HashMap<[usize; 2], (usize, usize)> = HashMap::new();
        let mut new_tet_indices: Vec<usize> = Vec::with_capacity(cavity.len());

        for (face, ext_nbr, ext_face_idx) in cavity {
            let [a, b, c] = face;
            let new_idx = self.alloc_tet(TetEntry {
                vertices: [a, b, c, pi],
                neighbors: [None; 4],
            });
            new_tet_indices.push(new_idx);

            // Wire the external neighbour across face 3.
            if let Some(n) = ext_nbr {
                self.tets[new_idx].as_mut().unwrap().neighbors[3] = Some(n);
                self.tets[n].as_mut().unwrap().neighbors[ext_face_idx] = Some(new_idx);
            }

            // Faces 0/1/2 each contain `pi` and one cavity edge:
            //   face 0 (opposite a) → edge (b,c)
            //   face 1 (opposite b) → edge (a,c)
            //   face 2 (opposite c) → edge (a,b)
            for (local_face_idx, (e0, e1)) in [(0, (b, c)), (1, (a, c)), (2, (a, b))] {
                let mut edge = [e0, e1];
                edge.sort_unstable();
                if let Some((other_idx, other_face)) = edge_pairing.remove(&edge) {
                    self.tets[new_idx].as_mut().unwrap().neighbors[local_face_idx] =
                        Some(other_idx);
                    self.tets[other_idx].as_mut().unwrap().neighbors[other_face] = Some(new_idx);
                } else {
                    edge_pairing.insert(edge, (new_idx, local_face_idx));
                }
            }
        }

        debug_assert!(
            edge_pairing.is_empty(),
            "cavity was not a closed polyhedron: {} unmatched edge(s)",
            edge_pairing.len()
        );

        self.last_inserted = new_tet_indices.first().copied();
    }

    pub(super) fn extract_mesh(&self) -> (Vec<Point>, Vec<[usize; 4]>) {
        let nodes = self.points[..self.num_real].to_vec();
        let mut elements = Vec::new();
        for tet in self.tets.iter().flatten() {
            if tet.vertices.iter().all(|&i| i < self.num_real) {
                elements.push(tet.vertices);
            }
        }
        (nodes, elements)
    }
}
